    target = np.array(target)
    previous_error = None
    stalled = 0
    for index in range(max_steps):
        current = np.array(obs['state'][arm + '_ee_pose'])
        delta = target[:3] - current[:3]
        distance = float(np.sqrt(np.sum(delta * delta)))
        q = target[3:7].copy()
        if float(np.sum(q * current[3:7])) < 0: q = -q
